import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers } from 'kea'
import { router } from 'kea-router'
import type { LocationChangedPayload } from 'kea-router/lib/types'

import { UniversalFiltersGroup } from '~/types'

import { LogsViewerFilters, LogsViewerScope } from 'products/logs/frontend/components/LogsViewer/config/types'

export interface OpenLogsViewerModalOptions extends LogsViewerScope {
    id?: string
    fullScreen?: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface logsViewerModalLogicValues {
    fullScreen: boolean
    initialFilters: Partial<LogsViewerFilters> | null
    isOpen: boolean
    personId: string | null
    pinnedFilters: UniversalFiltersGroup | null
    viewerId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface logsViewerModalLogicActions {
    locationChanged: ({
        method,
        pathname,
        search,
        searchParams,
        hash,
        hashParams,
        initial,
        url,
        routerState,
    }: LocationChangedPayload) => {
        hash: string
        hashParams: Record<string, any>
        initial: boolean
        method: 'POP' | 'PUSH' | 'REPLACE'
        pathname: string
        routerState: Record<string, any>
        search: string
        searchParams: Record<string, any>
        url: string
    } // router
    closeLogsViewerModal: () => {
        value: true
    }
    openLogsViewerModal: (options?: OpenLogsViewerModalOptions) => {
        fullScreen: boolean
        id: string
        initialFilters: Partial<LogsViewerFilters> | null
        personId: string | null
        pinnedFilters: UniversalFiltersGroup | null
    }
}

export type logsViewerModalLogicType = MakeLogicType<logsViewerModalLogicValues, logsViewerModalLogicActions>

export const logsViewerModalLogic = kea<logsViewerModalLogicType>([
    path(['products', 'logs', 'frontend', 'components', 'LogsViewer', 'LogsViewerModal', 'logsViewerModalLogic']),
    connect(() => ({
        actions: [router, ['locationChanged']],
    })),
    actions({
        openLogsViewerModal: (options?: OpenLogsViewerModalOptions) => ({
            id: options?.id ?? 'modal',
            fullScreen: options?.fullScreen ?? true,
            initialFilters: options?.initialFilters ?? null,
            pinnedFilters: options?.pinnedFilters ?? null,
            personId: options?.personId ?? null,
        }),
        closeLogsViewerModal: true,
    }),
    reducers({
        isOpen: [
            false,
            {
                openLogsViewerModal: () => true,
                closeLogsViewerModal: () => false,
            },
        ],
        viewerId: [
            'modal' as string,
            {
                openLogsViewerModal: (_, { id }) => id,
            },
        ],
        fullScreen: [
            true,
            {
                openLogsViewerModal: (_, { fullScreen }) => fullScreen,
            },
        ],
        // The three props below are what the modal binds its viewer with, and they deliberately
        // survive close. useKeepMountedWhileOpen holds the modal rendered for 300ms so the exit
        // animation can finish, so clearing them on close would rebind the viewer logics (shared
        // with the embedding tab, which is keyed by the same id) with no filters and no scope for
        // that beat, firing an unscoped project-wide query. Nothing leaks into the next open
        // because openLogsViewerModal always writes all three, falling back to null.
        initialFilters: [
            null as Partial<LogsViewerFilters> | null,
            {
                openLogsViewerModal: (_, { initialFilters }) => initialFilters,
            },
        ],
        pinnedFilters: [
            null as UniversalFiltersGroup | null,
            {
                openLogsViewerModal: (_, { pinnedFilters }) => pinnedFilters,
            },
        ],
        personId: [
            null as string | null,
            {
                openLogsViewerModal: (_, { personId }) => personId,
            },
        ],
    }),
    listeners(({ values, actions, cache }) => ({
        locationChanged: ({ pathname }) => {
            // close the (often full-screen) modal when navigating to a new scene, e.g. via cmd+k.
            // query/hash-only changes fire locationChanged too (the viewer syncs filters to the
            // URL), so only react to an actual pathname change.
            if (pathname === cache.lastPathname) {
                return
            }
            cache.lastPathname = pathname
            if (values.isOpen) {
                actions.closeLogsViewerModal()
            }
        },
    })),
    afterMount(({ cache }) => {
        cache.lastPathname = router.values.location.pathname
    }),
])
